mapper.select:
SELECT t.id AS id, t.app_ref_id AS appRefId, t.app_id AS appId, t.protocol AS protocol, t.event_type AS eventType, t.user_id AS userId, u.name AS userName, t.result AS result, t.fail_reason AS failReason, t.denied_policy_id AS deniedPolicyId, p.name AS deniedPolicyName, t.client_ip AS clientIp, t.session_id AS sessionId, t.user_agent AS userAgent, t.create_time AS createTime FROM tab_sso_protocol_log t LEFT JOIN tab_user u ON u.id = t.user_id LEFT JOIN tab_app_access_policy p ON p.id = t.denied_policy_id
AND t.app_ref_id = #{query.appRefId}
AND t.protocol = #{query.protocol}
AND t.event_type = #{query.eventType}
AND t.result = #{query.result}
AND t.session_id = #{query.sessionId}
AND t.create_time >= #{query.startTime}
AND t.create_time <= #{query.endTime}
ORDER BY t.create_time DESC, t.id DESC
